        raise ValueError("Invalid command specified. Must be a tuple.")
    if not varargs:
        raise ValueError("At least one argument must be provided.")
    for arg in varargs:
        if not isinstance(arg, str):
            raise ValueError(f"Invalid argument '{arg}'. Must be a string.")
    if target_concurrency <= 0:
        raise ValueError("target_concurrency must be a positive integer.")

    # Step 2: Make a pty if necessary
    pty = None
    if color and platform.platform_supports_pty():
        pty = platform.make_pty()
        stdin = pty.stdin
        stdout = pty.stdout
    else:
        stdin = sys.stdin
        stdout = sys.stdout

    # Step 3: Create the partitions
    partitions = []
    while len(partitions) < target_concurrency:
        partition = []
        while len(partition) < len(cmd):
            partition.append(varargs.pop(0))
        partitions.append(partition)

    # Step 4: Run the partitions concurrently
    result = []
    for partition in partitions:
        command = " ".join([cmd[i] for i in partition])
        process = subprocess.Popen(command, shell=True, stdin=stdin, stdout=stdout)
        result.append(process.communicate())

    # Step 5: Return the results
