def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows:
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if not cmd:
        return ()

    new_cmd = []
    for c in cmd:
        # Handle Windows-specific issues
        if is_windows():
            # Issue 8557: https://bugs.python.org/issue8557
            # Remove the first two characters from the command if they are backslashes
            if c[:2] == '\\':
                c = c[2:]

            # Remove any additional backslashes that may have been added
            c = c.strip('\\')

        # Handle deep-path shebangs
        if c == 'python' and len(cmd) > 1:
            c = 'python' + os.pathsep + ' '.join(cmd[1:])

        new_cmd.append(c)

    return tuple(new_cmd)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    # Step 1: Check if the input command is a tuple of strings
    if not isinstance(cmd, tuple):
        raise ValueError("Invalid input command. Must be a tuple of strings")
    for arg in cmd:
        if not isinstance(arg, str):
            raise ValueError("Invalid input command. Must be a tuple of strings")

    # Step 2: Check if the first argument is a shebang
    if not cmd[0].startswith("#!"):
        raise ValueError("Invalid shebang. Must start with '#!'")

    # Step 3: Fix for issue 8557
    # If the first argument starts with "#!C:/", it is a deep-path shebang.
    # In this case, we need to fix the path by removing the "C:/" part
    if cmd[0].startswith("#!C:/"):
        cmd[0] = "#!" + cmd[0].split("/C:/", 1)[1]

    # Step 4: Fix for issue with windows not parsing shebangs
    # If the first argument starts with "#!", it is a shebang.
    # In this case, we need to fix the path by prepending "C:/"
    if cmd[0].startswith("#!"):
        cmd[0] = "C:/" + cmd[0].split("#!", 1)[1]

    return tuple(cmd)

