def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if not callable(maxsize):
        raise TypeError("maxsize must be a callable")
    if not isinstance(ttl, int) or ttl <= 0:
        raise ValueError("ttl must be a positive integer")
    if timer is not None and not callable(timer):
        raise TypeError("timer must be a callable or None")
    if typed and not isinstance(typed, bool):
        raise TypeError("typed must be a boolean value")

    def decorator(func):
        cache_dict = {}
        hits = 0
        misses = 0
        access_times = {}
        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            now = timer()
            key = args + tuple(kwargs.items()) if typed else args
            try:
                access_time, value = cache_dict[key]
                if now - access_time < ttl:
                    hits += 1
                    return value
                else:
                    del cache_dict[key]
                    misses += 1
            except KeyError:
                misses += 1
            value = func(*args, **kwargs)
            cache_dict[key] = (now, value)
            access_times[key] = now
            hits += 1
            return value
            if len(cache_dict) > maxsize:
                oldest = min(access_times.items(), key=lambda x: x[1])
                del cache_dict[oldest[0]]
        return wrapper
    return decorator

