def extostr(e, max_level=30, max_path_level=5):
    # Check if the input is an exception instance
    if not isinstance(e, Exception):
        raise TypeError("extostr() argument must be an exception instance")

    # Set the maximum level and path level
    if not isinstance(max_level, int) or max_level < 0:
        max_level = 30
    if not isinstance(max_path_level, int) or max_path_level < 0:
        max_path_level = 5

    # Format the exception
    exception_str = "{}: {}".format(e.__class__.__name__, str(e))
    trace = inspect.getframeinfo(inspect.currentframe())
    stack_level = 0
    for frame in trace:
        if stack_level > max_level:
            break
        stack_level += 1
        filename, lineno, function, _, _ = frame
        filename = os.path.basename(filename)
        if filename == "<string>":
            continue
        exception_str += "\n  File \"{}\", line {}, in {}".format(filename, lineno, function)
        for i, path in enumerate(inspect.getfile(frame)):
            if i > max_path_level:
                break
            exception_str += "\n    {}".format(path)

    return exception_str + "\n"

def append_text_to_file(file_name, text_buffer, encoding, overwrite=False):
    # Raise exception if file_name is not a string
    if not isinstance(file_name, str):
        raise TypeError("file_name must be a string")

    # Raise exception if text_buffer is not a string
    if not isinstance(text_buffer, str):
        raise TypeError("text_buffer must be a string")

    # Raise exception if encoding is not a string
    if not isinstance(encoding, str):
        raise TypeError("encoding must be a string")

    # Raise exception if overwrite is not a boolean
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a boolean")

    # Open the file in append mode, create it if it does not exist
    try:
        with open(file_name, 'ab' if overwrite else 'a+b') as f:
            # Convert the text_buffer to binary data using the specified encoding
            binary_data = text_buffer.encode(encoding)
            # Write the binary data to the file
            f.write(binary_data)
            # Return the number of bytes written
            return len(binary_data)
    # Raise an exception if the file could not be opened or written to
    except (IOError, OSError) as e:
        raise e

