def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Check if the input is valid
    if not bins or not edges:
        raise ValueError("Invalid input")

    # Compute the integral
    integral = 0
    for i in range(len(bins)):
        for j in range(len(edges)-1):
            if bins[i] >= edges[j] and bins[i] < edges[j+1]:
                integral += (bins[i] - edges[j]) * (edges[j+1] - edges[j])

    return integral

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Check inputs
    if not isinstance(bins, np.ndarray):
        raise TypeError("bins must be a numpy array")
    if not isinstance(edges, np.ndarray):
        raise TypeError("edges must be a numpy array")
    if bins.shape != edges.shape:
        raise ValueError("bins and edges must have the same shape")
    if bins.ndim != 1:
        raise ValueError("bins must be a 1D array")
    if edges.ndim != 1:
        raise ValueError("edges must be a 1D array")

    # Compute integral
    integral = 0
    for i in range(bins.size):
        bin_valid = bins[i]
        edge_left = edges[i]
        edge_right = edges[i+1]
        if bin_valid:
            integral += (edge_right - edge_left) * bin_valid

    return integral

def integral(bins, edges):
    if not isinstance(bins, np.ndarray) or not isinstance(edges, np.ndarray):
        raise ValueError("bins and edges must be numpy arrays")
    if len(bins) != len(edges) - 1:
        raise ValueError("length of bins must be one less than length of edges")
    if not np.all(np.diff(edges) > 0):
        raise ValueError("edges must be strictly increasing")

    area = 0
    for i in range(len(bins)):
        area += bins[i] * (edges[i + 1] - edges[i])

    return area

