        raise ValueError("No digests are used in the manifest")

    # Check if all digests in digests_used are present in manifest_files
    if not (set(digests_used) <= set(manifest_files)):
        raise ValueError("One or more digests in digests_used are not present in manifest_files")

    # Check if all digests in manifest_files are used in digests_used
    if not (set(manifest_files) <= set(digests_used)):
        raise ValueError("One or more digests in manifest_files are not used in digests_used")

    # All checks pass, return True
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Step 1: Check that all digests in the manifest files are present in the digests_used set.
    # If any digests are missing, raise a MissingDigestError.
    missing_digests = set()
    for filename, manifest in manifest_files.items():
        for expected_digest in manifest:
            if expected_digest not in digests_used:
                missing_digests.add(expected_digest)
    if missing_digests:
        raise MissingDigestError(missing_digests)

    # Step 2: Check that all digests in the digests_used set are present in the manifest files.
    # If any digests are extra, raise an ExtraDigestError.
    extra_digests = set()
    for filename, manifest in manifest_files.items():
        for actual_digest in manifest:
            if actual_digest not in digests_used:
                extra_digests.add(actual_digest)
    if extra_digests:
        raise ExtraDigestError(extra_digests)

    # Step 3: Check that all digests in the manifest files are used in the manifest.
    # If any digests are unused, raise an UnusedDigestError.
    unused_digests = set()
    for filename, manifest in manifest_files.items():
        for expected_digest in manifest:
            if expected_digest not in digests_used:
                unused_digests.add(expected_digest)
    if unused_digests:
        raise UnusedDigestError(unused_digests)

    # Step 4: Return True if all digests are present, used, and unused.
    return True

