def get_logical_path_map(inventory, version):
    # Step 1: Filter the inventory to only include content files for the specified version
    content_inventory = inventory.where(version=version)

    # Step 2: Build a map of logical paths to sets of content files
    logical_path_map = {}
    for content_file in content_inventory:
        logical_path_map.setdefault(content_file.logical_path, set())
        logical_path_map[content_file.logical_path].add(content_file)

    # Step 3: Return the map of logical paths to sets of content files
    return logical_path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for file in inventory:
        if file.version == version:
            logical_path = file.logical_path
            if logical_path not in logical_path_map:
                logical_path_map[logical_path] = set()
            logical_path_map[logical_path].add(file.name)
    return logical_path_map

def get_logical_path_map(inventory, version):
    if not isinstance(inventory, dict) or not isinstance(version, str):
        raise TypeError("Invalid inventory or version type")
    if version not in inventory:
        raise ValueError("Version not found in inventory")
    logical_path_map = {}
    for v in inventory[version]:
        logical_path_map[v["logical_path"]] = v["content_files"]
    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise TypeError("Fixity block must be a dictionary")

    if not fixity:
        raise ValueError("Fixity block cannot be empty")

    for hash_type, file_hashes in fixity.items():
        if not isinstance(file_hashes, list):
            raise TypeError(f"File hashes for {hash_type} must be a list")

        for file_hash in file_hashes:
            if not isinstance(file_hash, dict):
                raise TypeError(f"File hash for {hash_type} must be a dictionary")

            file_name = file_hash.get("name")
            if not file_name:
                raise ValueError(f"File name not found for {hash_type}")

            if file_name not in manifest_files:
                raise ValueError(f"File {file_name} not found in manifest")

            hash_value = file_hash.get("value")
            if not hash_value:
                raise ValueError(f"Hash value not found for file {file_name}")

            if not isinstance(hash_value, str):
                raise ValueError("Hash value must be a string")

            if not re.match(r"[0-9a-f]{40}", hash_value, re.IGNORECASE):
                raise ValueError(f"Invalid hash value for file {file_name}: {hash_value}")

    return True

