def _extract_number_and_supplment_from_issue_element(issue):
    try:
        issue = issue.rstrip().lstrip()
        if issue.upper().startswith("<ISSUE>"):
            issue = issue.replace("<ISSUE>", "").replace("</ISSUE>", "")
        issue = issue.replace("&", "").replace(";", "")
        issue = issue.replace("SUPPL", "").replace("SUPPLEM", "")
        issue = issue.replace("SPE", "").replace("PR", "")
        issue = issue.repalce("Suppl.", "").replace("Suppl", "")
        issue = issue.repalce("spe", "").replace("Spe", "")
        issue = issue.repalce("supp", "").replace("Supp", "")
        issue_parts = issue.split(" ", 1)
        if len(issue_parts) < 2:
            number = issue_parts[0]
            supplement = ""
        else:
            number = issue_parts[0]
            supplement = " ".join(issue_parts[1:]).strip()
        return (number, supplement)
    except:
        return ("", "")

