def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expressions applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    output = []
    for expr in args:
        if isinstance(expr, And):
            left, right = expr.operands
            if isinstance(right, Or):
                left_absorbed, right_absorbed = absorb(self, [left, right.operands[0]])
                output.append(Or(left_absorbed, right_absorbed))
            elif isinstance(right, Not) and isinstance(right.operand, Or):
                left_absorbed, right_absorbed = absorb(self, [left, right.operand.operands[0]])
                output.append(And(left_absorbed, right_absorbed))
            else:
                output.append(expr)
        elif isinstance(expr, Or):
            left, right = expr.operands
            if isinstance(left, Not) and isinstance(left.operand, Or):
                left_absorbed, right_absorbed = absorb(self, [left.operand.operands[0], right])
                output.append(Or(left_absorbed, right_absorbed))
            elif isinstance(right, And):
                left_absorbed, right_absorbed = absorb(self, [left, right.operands[0]])
                output.append(Or(left_absorbed, right_absorbed))
            else:
                output.append(expr)
        else:
            output.append(expr)
    return output

def on(self, hook: HookType) -> callable:
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # If the hook is already registered, append the new handler
            if hook in self._hooks:
                self._hooks[hook].append(func)
            # Otherwise, create a new list for the hook and add the handler
            else:
                self._hooks[hook] = [func]
            return func(*args, **kwargs)
        return wrapper
    return decorator

def normalized(self):
