    if not isinstance(self.days, (int, float)):
        raise TypeError("Invalid type for 'days' attribute. Must be an integer or float.")
    if not isinstance(self.hours, (int, float)):
        raise TypeError("Invalid type for 'hours' attribute. Must be an integer or float.")

