        return self
    if self.days is not None and self.hours is not None:
        return relativedelta(days=self.days, hours=self.hours)
    if self.days is None:
        days = self.hours // 24
        hours = self.hours % 24
        return relativedelta(days=days, hours=hours)
    if self.hours is None:
        hours = self.days * 24
        return relativedelta(days=self.days, hours=hours)

