def _call_tzname_func(namefunc):
    # Call with the appropriate arguments
    if PYTHON_VERSION == 2:
        return namefunc(None, -1)
    elif PYTHON_VERSION == 3:
        return namefunc(None)
    else:
        raise ValueError("Unknown Python version: %s" % PYTHON_VERSION)

