def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        if cwd is not None:
            os.chdir(cwd)
        if isinstance(commands, str):
            commands = [commands]
        for command in commands:
            if verbose:
                print(f"Calling command: {command}")
            args = [str(arg) for arg in args]
            result = subprocess.run(command, args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
            if result.returncode != 0:
                raise RuntimeError(f"Command {command} exited with status code {result.returncode}")
            if verbose:
                print(f"Command {command} finished with status code {result.returncode}")
        return result.stdout.decode()
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {e.strerror}")
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Command {command} failed with error code {e.returncode}")
    except Exception as e:
        raise RuntimeError(f"Unknown error: {e}")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    from subprocess import Popen, PIPE, STDOUT

    if not commands:
        raise ValueError("No commands specified")

    if not isinstance(commands, list):
        commands = [commands]

    if not isinstance(args, list):
        args = [args]

    if cwd is None:
        cwd = os.getcwd()

    if env is None:
        env = os.environ.copy()

    command_string = " ".join(commands)
    command_args = [command_string] + args

    if not hide_stderr:
        command_args += ["2>&1"]

    proc = Popen(command_args, stdout=PIPE, stderr=STDOUT, cwd=cwd, env=env)
    output = proc.communicate()[0].decode("utf-8")

    if verbose:
        print(output)

    return output

