    """Call the given command(s)."""
    if not commands:
        raise ValueError("No commands provided")
    if not args:
        raise ValueError("No arguments provided")
    if not cwd:
        cwd = os.getcwd()
    if not os.path.isdir(cwd):
        raise ValueError("Current working directory is not valid")

    if verbose:
        print("Running command(s):")
        print(" ".join(commands))

    process = subprocess.Popen(commands, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=cwd, env=env)
    stdout, stderr = process.communicate()

    if verbose:
        print("stdout:")
        print(stdout)
        print("stderr:")
        print(stderr)

    if process.returncode != 0:
        raise RuntimeError("Command(s) failed with code {}, check stderr for details".format(process.returncode))

    if hide_stderr:
        stderr = b""

    return stdout, stderr

