    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Validate the root directory
    if not self.root_dir.exists():
        raise FileNotFoundError(f"Root directory '{self.root_dir}' does not exist")

    # Validate the all directories and files
    for parent, subfolders, files in os.walk(self.root_dir):
        # Validate directories
        for directory in subfolders:
            num_objects += 1
            path = os.path.join(parent, directory)
            if not os.path.isdir(path):
                raise FileNotFoundError(f"Directory '{path}' does not exist")
            if validate_objects and not self.validate_directory(path):
                raise InvalidObjectException(f"Directory '{path}' is not valid")
            if check_digests and not self.validate_directory_digests(path):
                raise InvalidDigestException(f"Directory '{path}' has invalid digest")
            if show_warnings:
                print(f"Directory '{path}' is valid")

        # Validate files
        for file in files:
            num_objects += 1
            path = os.path.join(parent, file)
            if not os.path.isfile(path):
                raise FileNotFoundError(f"File '{path}' does not exist")
            if validate_objects and not self.validate_file(path):
                raise InvalidObjectException(f"File '{path}' is not valid")
            if check_digests and not self.validate_file_digests(path):
                raise InvalidDigestException(f"File '{path}' has invalid digest")
            if show_warnings:
                print(f"File '{path}' is valid")

    # Return the number of objects checked and the number of valid objects
    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Check if storage root is valid
    if not self.is_valid():
        raise ValueError("Storage root is not valid")

    # Get all objects in the storage root
    objects = self.get_all_objects()
    num_objects = len(objects)

    # Validate objects if requested
    good_objects = 0
    if validate_objects:
        for object in objects:
            try:
                if object.is_valid():
                    good_objects += 1
            except AttributeError:
                raise ValueError("Object {0} is not a valid object".format(object))

    # Check digests if requested
    if check_digests:
        for object in objects:
            try:
                if not object.is_digest_valid():
                    raise ValueError("Digest for object {0} is not valid".format(object))
            except AttributeError:
                raise ValueError("Object {0} is not a valid object".format(object))

    # Return the number of objects and the number of good objects
    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        version_parts = version.split(".")
        if len(version_parts) != 3:
            raise ValueError("Invalid version")
        major, minor, patch = map(int, version_parts)
        return f"{major}.{minor}.{patch+1}"
    except ValueError:
        return version

