def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Step 1: Check if the input parameters are valid
    if not params or not bug_ids:
        raise ValueError("Invalid input parameters")

    # Step 2: Initialize the amended parameters dictionary
    amended_params = {}

    # Step 3: Loop through the bug IDs and amend the parameters
    for bug_id in bug_ids:
        # Step 3A: Retrieve the bug from Bugzilla
        bug = self.bugzilla.getbug(bug_id)

        # Step 3B: Check if the bug exists
        if bug is None:
            raise Exception(f"Bug {bug_id} does not exist")

        # Step 3C: Amend the bug's parameters
        bug_status = bug.status
        if bug_status == "RESOLVED":
            amended_params[bug_id] = "CLOSED"
        elif bug_status == "CLOSED":
            amended_params[bug_id] = "RESOLVED"
        else:
            amended_params[bug_id] = bug_status

    return amended_params

