def deep_merge_nodes(nodes):
    """
    Given a list of tuples where each tuple contains a ScalarNode as a key and a
    MappingNode or other Node as a value, deep merge any node values corresponding to
    duplicate keys and return the result. If there are colliding keys with non-MappingNode
    values (e.g., integers or strings), the last of the values wins.
    """
    result = []
    seen_keys = set()
    for node in nodes:
        if isinstance(node[0], ScalarNode) and isinstance(node[1], MappingNode):
            if node[0].value not in seen_keys:
                result.append(node)
                seen_keys.add(node[0].value)
            else:
                for i, existing_node in enumerate(result):
                    if existing_node[0].value == node[0].value:
                        result[i] = (existing_node[0], deep_merge_nodes([(existing_node[1], node[1])]))
                        break
        else:
            result.append(node)
    return result

