    parsed_arguments = {}

    # Loop through the unparsed arguments and parse them
    for argument in unparsed_arguments:
        # Check if the argument is a subparser name
        if argument.startswith("--"):
            # Extract the subparser name and create a new entry in the dictionary
            subparser_name = argument[2:]
            parsed_arguments[subparser_name] = argparse.Namespace()

        # Check if the argument is a global option
        elif argument.startswith("-"):
            # Extract the global option and add it to the global namespace
            global_option = argument[1:]
            parsed_arguments["global"].add_argument(global_option)

