def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    import inspect
    import borgmatic.core.cli

    def get_options(cmd):
        options = []
        for name, param in inspect.signature(cmd.__call__).parameters.items():
            if param.kind == inspect.Parameter.KEYWORD_ONLY:
                options.append(name)
        return options

    def get_commands():
        commands = []
        for name, cmd in borgmatic.core.cli.commands.items():
            if isinstance(cmd, borgmatic.core.cli.Command):
                commands.append(name)
        return commands

    def get_command_options(cmd):
        return get_options(cmd)

    def get_option_kwargs(cmd, option):
        kwargs = {}
        for name, param in inspect.signature(cmd.__call__).parameters.items():
            if param.kind == inspect.Parameter.KEYWORD_ONLY:
                kwargs[name] = param.default
        return kwargs[option]

    def get_command_help(cmd):
        return cmd.__doc__.splitlines()[0]

    def get_option_help(cmd, option):
        return get_command_help(cmd)

