    # Step 1: Create a dictionary to store the parsed arguments for each subparser
    subparser_arguments = {name: {} for name in subparsers}

    # Step 2: Iterate over the unparsed arguments and try to parse each one with each subparser
    for argument in unparsed_arguments:
        for name, subparser in subparsers.items():
            try:
                subparser_arguments[name].update(subparser.parse_args([argument]))
            except ArgumentParserError:
                # If the argument cannot be parsed by this subparser, move on to the next one
                continue
            else:
                # If the argument is successfully parsed by a subparser, stop trying further subparsers
                break
        else:
            # If the argument cannot be parsed by any subparser, add it to the list of remaining arguments
            remaining_arguments.append(argument)

    # Step 3: Return the dictionary of parsed arguments and the list of remaining arguments
    return subparser_arguments, remaining_arguments

