def vertex3tuple(vertices):
    """Return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex.

    :param vertices: The vertices of the polygon.
    :type vertices: list

    :return: A list of 3-tuples, where each tuple contains the vertex and the 2 points on both sides of the vertex.
    :rtype: list
    """
    if not vertices:
        raise ValueError("Vertices list cannot be empty")

    output = []
    for i in range(len(vertices)):
        if i == 0:
            p1, p2, p3 = vertices[-1], vertices[0], vertices[1]
        elif i == len(vertices) - 1:
            p1, p2, p3 = vertices[-2], vertices[-1], vertices[0]
        else:
            p1, p2, p3 = vertices[i-1], vertices[i], vertices[i+1]
        output.append((p1, p2, p3))

    return output

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise ValueError(f"Expected an integer, got {type(number).__name__}")
    if not isinstance(alphabet, list):
        raise ValueError(f"Expected a list, got {type(alphabet).__name__}")
    if not all(isinstance(x, str) for x in alphabet):
        raise ValueError("Expected a list of strings")
    if padding is not None and (not isinstance(padding, int) or padding < 0):
        raise ValueError(f"Expected a non-negative integer for padding, got {type(padding).__name__}")

    result = ""
    if number == 0:
        return alphabet[0]

    while number > 0:
        result = alphabet[number % len(alphabet)] + result
        number //= len(alphabet)

    if padding is not None:
        result = result.rjust(padding, alphabet[0])

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is not None and padding < 0:
        raise ValueError("padding must be a non-negative integer")

    if not isinstance(number, int):
        raise TypeError("number must be an integer")

    if not isinstance(alphabet, list) or not all(isinstance(x, str) for x in alphabet):
        raise TypeError("alphabet must be a list of strings")

    if not alphabet:
        raise ValueError("alphabet cannot be empty")

    base = len(alphabet)
    result = ""
    while number > 0:
        number, remainder = divmod(number, base)
        result = alphabet[remainder] + result

    if padding is not None:
        result = result.rjust(padding, alphabet[0])

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """

    if not isinstance(number, int):
        raise ValueError(f"Invalid input number: {number}")

    if not isinstance(alphabet, list):
        raise ValueError(f"Invalid input alphabet: {alphabet}")

    if padding is not None and not isinstance(padding, int):
        raise ValueError(f"Invalid input padding: {padding}")

    if number == 0:
        return "0"

    if alphabet.is_empty():
        raise ValueError("Alphabet must not be empty")

    # construct a list of the digits in the number
    digits = []
    while number > 0:
        remainder = number % len(alphabet)
        digits.append(alphabet[remainder])
        number //= len(alphabet)

    # construct the output string
    result = ""
    for digit in digits:
        result = digit + result

    if padding is not None and len(result) < padding:
        result = "0" * (padding - len(result)) + result

    return result

