def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    subclasses = []
    worklist = [cls]
    while worklist:
        parent = worklist.pop()
        for child in parent.__subclasses__():
            if child not in subclasses:
                subclasses.append(child)
                worklist.append(child)
    return subclasses

def string_to_int(string: str, alphabet: List[str]) -> int:
    if not string or not alphabet:
        raise ValueError("Invalid input")
    if len(alphabet) < 2:
        raise ValueError("Alphabet must have at least 2 characters")
    if any(not c.isalpha() for c in alphabet):
        raise ValueError("Alphabet must only contain letters")

    number = 0
    for i, c in enumerate(string):
        if c not in alphabet:
            raise ValueError(f"Invalid character '{c}' in input string")
        number += (alphabet.index(c) + 1) * (len(alphabet) ** i)

    return number

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not string:
        return 0

    if not alphabet:
        raise ValueError("Alphabet must not be empty.")

    base = len(alphabet)
    value = 0
    for i, char in enumerate(string):
        if char not in alphabet:
            raise ValueError(f"Invalid character '{char}' in input string.")
        value += alphabet.index(char) * base ** i

    return value

