    try:
        response = requests.get(url, stream=True)
        response.raise_for_status()
        # check that the response is a .tar.gz archive
        if response.headers.get("Content-Type") != "application/x-gzip":
            raise ValueError("The response is not a .tar.gz archive")
        # extract the archive to the destination path
        archive = tarfile.open(fileobj=response.raw, mode="r:gz")
        archive.extractall(path=destination_path)
        return destination_path
    except requests.exceptions.RequestException as e:
        raise RuntimeError(f"Error downloading archive from {url}: {e}") from e
    except ValueError as e:
        raise RuntimeError(f"Error extracting archive from {url}: {e}") from e

