import re

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
    # Determine the current platform at runtime using the os module.
        platform = '1' if os.name == 'posix' else '0'
    if platform == '1':
        return re.split(r'\s+', s)
    else:
        return re.split(r'(\s+|((?<!\\)\\"|(?<!\\)\"|(?<!\\)\')(?:(?:[^\\"\'](?:\\\\)*(?:"|\'))+|(?:\\\\(?:"|\'))*[^\\"\'](?:\\\\)*))', s)

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Initialize variables
    platform = platform.lower()
    posix_pattern = r"[^\s\"']+|\"[^\"]*\"|'[^']*'"
    windows_pattern = r"[^\s\"]+(\"[^\"]*\"|\\\"|'[^']*'|\\')+"

    # Handle platform auto-detection
    if platform == 'this':
        import platform
        platform = platform.system()
        if platform == 'Windows':
            platform = '0'
        else:
            platform = '1'

    # Handle different platforms
    if platform == '0':
        pattern = windows_pattern
    elif platform == '1':
        pattern = posix_pattern
    else:
        raise ValueError("Invalid platform specified")

    # Split the string using the specified pattern
    matches = re.findall(pattern, s)

    # Remove outer quotes and unescape escaped quotes
    for i in range(len(matches)):
        if matches[i][0] == '"' and matches[i][-1] == '"':
            matches[i] = matches[i][1:-1].replace('\\"', '"')
        elif matches[i][0] == "'" and matches[i][-1] == "'":
            matches[i] = matches[i][1:-1].replace("\\'", "'")

    # Return the list of parsed arguments
    return matches

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = ('posix' if sys.platform.lower() in {'linux', 'darwin'} else 'windows')
    elif platform == 1:
        platform = 'posix'
    elif platform == 0:
        platform = 'windows'

    if platform == 'posix':
