def split(s, platform='this'):
    import re
    if platform == 'this':
        platform = 'win32' if os.name == 'nt' else 'posix'
    if platform == 'win32':
        regex = r'(?:"(.+?)"|(?<=,|^)(?!.+?,)(?:\S|\S.*?\S)(?<!,))'
    else:
        regex = r'"((?:\\.|[^"])*)"|(\\.)|(\S+)'
    args = re.findall(regex, s)
    return [x or y or z for x, y, z in args]

