def _split_windows(s):
    parts = s.split()
    result = []
    for part in parts:
        if not part:
            continue
        stripped = part.strip()
        if len(stripped) >= 2 and stripped[0] == '"' and stripped[-1] == '"':
            result.append(stripped[1:-1])
        else:
            result.append(stripped)
    return result
