def _resolve_env_variables(data):
    # Use a regular expression to find and replace environment variables in the data
    env_var_pattern = r'\${([a-zA-Z_][a-zA-Z0-9_]*)}'
    for match in re.finditer(env_var_pattern, data):
        var_name = match.group(1)
        try:
            var_value = os.environ[var_name]
            data = data.replace(match.group(0), var_value)
        except KeyError:
            pass
    return data

