    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    configurations = {}
    errors = []

    for config_filename in config_filenames:
        try:
            with open(config_filename, 'r') as file:
                config = yaml.safe_load(file)
        except FileNotFoundError as e:
            errors.append(logging.LogRecord(
                level=logging.ERROR,
                msg=f"Configuration file '{config_filename}' not found.",
                exc_info=e,
            ))
            continue
        except yaml.YAMLError as e:
            errors.append(logging.LogRecord(
                level=logging.ERROR,
                msg=f"Failed to parse configuration file '{config_filename}'.",
                exc_info=e,
            ))
            continue

        if resolve_env and 'env' in config:
            for key, value in config['env'].items():
                if isinstance(value, str):
                    config['env'][key] = os.path.expandvars(value)

        configurations[config_filename] = config

    return configurations, errors

