            f"{candidate} does not provide the expected interface {iface}"
        )

    # Check if the candidate defines all necessary methods
    expected_methods = getattr(iface, 'methods', ())
    if expected_methods:
        defined_methods = {a for a in dir(candidate) if callable(getattr(candidate, a, None))}
        missing_methods = expected_methods - defined_methods
        if missing_methods:
            raise zope.interface.Invalid(
                f"{candidate} does not define the expected method(s): {', '.join(sorted(missing_methods))}"
            )

    # Check if the candidate defines all necessary attributes
    expected_attributes = getattr(iface, 'attributes', ())
    if expected_attributes:
        defined_attributes = set(a for a in dir(candidate) if not callable(getattr(candidate, a, None)))
        missing_attributes = expected_attributes - defined_attributes
        if missing_attributes:
            raise zope.interface.Invalid(
                f"{candidate} does not define the expected attribute(s): {', '.join(sorted(missing_attributes))}"
            )

    # Check if the methods have the correct signature
    if expected_methods:
        for method in expected_methods:
            if not inspect.ismethod(getattr(candidate, method, None)):
                raise zope.interface.Invalid(
                    f"Invalid signature for method {method} in {candidate}"
