def set_cut_chars(self, before: bytes, after: bytes) -> None:
    """Set the bytes used to delimit slice points.

    Args:
        before: Split file before these delimiters.
        after: Split file after these delimiters.
    """
    if not isinstance(before, bytes) or not isinstance(after, bytes):
        raise ValueError("before and after must be of type bytes")

    self._cut_chars_before = before
    self._cut_chars_after = after

    # Update the cache
    self._update_cache()

def _update_cache(self) -> None:
    """Update the cache of split strings."""
    self._split_strings = {}
    for idx, string in enumerate(self._original_string):
        if string in self._cut_chars_before:
            self._split_strings[idx] = string
    for idx, string in enumerate(self._original_string):
        if string in self._cut_chars_after:
            self._split_strings[idx] = string

def __getitem__(self, key: int) -> str:
    """Get the cached split string at the given index."""
    if not isinstance(key, int):
        raise TypeError("key must be of type int")
    if key not in self._split_strings:
        raise KeyError("key not found in cache")
    return self._split_strings[key]

def __iter__(self) -> SplitStringIterator:
    """Return an iterator over the cached split strings."""
    return SplitStringIterator(self)

class SplitStringIterator:
    """Iterator over the cached split strings."""

    def __init__(self, split_string: SplitString) -> None:
        self._split_string = split_string
        self._idx = 0

    def __next__(self) -> str:
        if self._idx < len(self._split_string):
            string = self._split_string[self._idx]
            self._idx += 1
            return string
        raise StopIteration

def __reversed__(self) -> ReverseSplitStringIterator

