def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversion - child nodes are not recursively processed.
    """
    children = node.children
    # check if the node has any children
    if not children:
        return {}

    # create a dict to store the child elements keyed by their tag name
    child_dict = {}

    # loop through the children and extract their tag name and text content
    for child in children:
        # check if the child is an element node
        if child.nodeType == Node.ELEMENT_NODE:
            # get the tag name of the child element
            tag_name = child.tagName.lower()

            # check if the tag name is already in the dict
            if tag_name in child_dict:
                # if the tag name is already in the dict, append the text content to the existing list
                child_dict[tag_name].append(child.textContent)
            else:
                # if the tag name is not in the dict, create a new list with the text content
                child_dict[tag_name] = [child.textContent]

    return child_dict

