def parse_diaspora_webfinger(document: str) -> Dict:
    try:
        # If the MIME type is application/jrd+json, parse it as JSON
        if document.startswith("{"):
            data = json.loads(document)
            return {
                "subject": data.get("subject"),
                "links": [
                    {"rel": link["rel"], "href": link["href"], "type": link["type"]}
                    for link in data.get("links", [])
                ]
            }
        # Otherwise, parse it as an XRD document
        else:
            (_, _, json_data) = document.partition("application/jrd+json")
            return json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("Invalid Diaspora webfinger document")

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        json_data = json.loads(document)
        return json_data
    except json.JSONDecodeError:
        pass

    try:
        xrd_data = XRD.parse(document)
        return xrd_data.to_dict()
    except XRDError:
        raise ValueError("Invalid Diaspora webfinger format")

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        json_data = json.loads(document)
        xrd_data = {}
        for key, value in json_data.items():
            if isinstance(value, str):
                xrd_data[key] = value
        return xrd_data
    except json.JSONDecodeError as e:
        xrd_data = parse_xrd(document)
        return xrd_data

def parse_xrd(document: str) -> Dict:
    """
    Parse an XRD document.
    """
    xrd_data = {}
    for section in document.split("\n"):
        if section.startswith("{"):
            xrd_data["root"] = section.strip("{")
        elif section.startswith("}"):
            xrd_data["__end__"] = section.strip("}")
    return xrd_data

