        raise DiasporaHostMetaRetrievalError("Connection Error")
    except XRD.ParseError:
        raise DiasporaHostMetaRetrievalError("Invalid host-meta document")

def retrieve_diaspora_host_meta(host):
    try:
        request = Request(f"https://{host}/.well-known/host-meta.json", headers={
            "User-Agent": f"Diaspora/{VERSION}"
        })
        response = urlopen(request)
        data = response.read()
        xrd = XRD.from_json(data.decode("utf-8"))
        return xrd
    except (HTTPError, URLError) as e:
        raise DiasporaHostMetaError(f"Failed to retrieve host-meta document for {host}") from e

