def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    :param self: The object that contains the spec and other sources.
    :type self: Any
    :return: A dictionary of resolved argument values.
    :rtype: dict
    :raise ValueError: If there are conflicting values for an argument.
    """
    # Step 1: Collect all possible values for each argument.
    spec_args = {}
    for arg_name, arg_value in self.spec.items():
        if arg_name not in spec_args:
            spec_args[arg_name] = set()
        spec_args[arg_name].add(arg_value)
    for source in self.sources:
        for arg_name, arg_value in source.items():
            if arg_name not in spec_args:
                spec_args[arg_name].add(arg_value)

    # Step 2: Resolve conflicts by selecting the first non-None value.
    resolved_args = {}
    for arg_name, arg_values in spec_args.items():
        resolved_args[arg_name] = next((arg_value for arg_value in arg_values if arg_value is not None), None)

    # Step 3: Check for conflicts.
    for arg_name, arg_value in resolved_args.items():
        if arg_value is None:
            raise ValueError(f"No value found for argument '{arg_name}'")

    return resolved_args

