    if not os.environ.get('CONFIG_PATH'):
        os.environ['CONFIG_PATH'] = os.path.join(os.path.dirname(os.path.abspath(__file__)), '../config.ini')

def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to to the main entry point.

    :param subparser: the subparser object to extend.
    """
    try:
        root_subparsers.add_parser('spec', help="Execute the spec tests")
    except argparse.ArgumentError:
        pass

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Path and root must be strings")
    if not path.startswith(root):
        raise ValueError("Path does not start with root")
    return path[len(root):]

